// Haversine distance helper in kilometers
export function calculateHaversineDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth radius in km
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

// Distance from point to line segment
function distanceToSegment(pLat, pLng, aLat, aLng, bLat, bLng) {
  const lineDist = calculateHaversineDistance(aLat, aLng, bLat, bLng);
  if (lineDist === 0) return calculateHaversineDistance(pLat, pLng, aLat, aLng);

  // Projection scalar t
  const dx = bLng - aLng;
  const dy = bLat - aLat;
  const t = Math.max(0, Math.min(1, ((pLng - aLng) * dx + (pLat - aLat) * dy) / (dx * dx + dy * dy)));
  const projLat = aLat + t * dy;
  const projLng = aLng + t * dx;
  return calculateHaversineDistance(pLat, pLng, projLat, projLng);
}

// ==============================================================================
// Dynamic Flood-Aware Routing Engine
// Calculates safe flyover bypasses & clearance thresholds
// ==============================================================================
export function calculateDynamicRoute(origin, destination, selectedCity, vehicle, incidents, resolvedRealRoute = null) {
  const cityDefaults = MULTI_CITY_ROUTES[selectedCity] || MULTI_CITY_ROUTES.BLR;
  if (!origin || !destination) {
    return cityDefaults;
  }

  const cityIncidents = incidents || [];
  const baseDistance = calculateHaversineDistance(origin.lat, origin.lng, destination.lat, destination.lng);

  // Check if current points closely match the pre-computed city corridor
  const isDefaultCorridor =
    cityDefaults &&
    Math.abs(origin.lat - cityDefaults.origin.lat) < 0.005 &&
    Math.abs(origin.lng - cityDefaults.origin.lng) < 0.005 &&
    Math.abs(destination.lat - cityDefaults.destination.lat) < 0.005 &&
    Math.abs(destination.lng - cityDefaults.destination.lng) < 0.005;

  let directPath = [];
  let defaultDetour = [];

  if (resolvedRealRoute && resolvedRealRoute.directPath && resolvedRealRoute.directPath.length > 0) {
    directPath = resolvedRealRoute.directPath;
    defaultDetour = resolvedRealRoute.detourPath || resolvedRealRoute.directPath;
  } else if (isDefaultCorridor) {
    directPath = cityDefaults.directPath;
    defaultDetour = cityDefaults.detourPath;
  } else {
    // If real route is still resolving, create intermediate waypoints rather than a straight diagonal
    const steps = 8;
    for (let i = 0; i <= steps; i++) {
      const ratio = i / steps;
      directPath.push([
        origin.lat + (destination.lat - origin.lat) * ratio,
        origin.lng + (destination.lng - origin.lng) * ratio
      ]);
    }
  }

  // 2. Detect any flood incidents along the corridor (within 0.8 km of the path)
  let worstHazard = null;
  cityIncidents.forEach((inc) => {
    const distToCorridor = distanceToSegment(
      inc.lat,
      inc.lng,
      origin.lat,
      origin.lng,
      destination.lat,
      destination.lng
    );

    if (distToCorridor <= 1.4) {
      if (!worstHazard || inc.depthCm > worstHazard.depthCm) {
        worstHazard = inc;
      }
    }
  });

  // Vehicle clearance limits
  const VEHICLE_THRESHOLDS = {
    BIKE: 20,
    SEDAN: 30,
    SUV: 55
  };

  const limit = VEHICLE_THRESHOLDS[vehicle] || 20;
  const isBlocked = worstHazard && worstHazard.depthCm >= limit;

  // 3. Build Detour Path if blocked
  let detourPath = [];
  if (isBlocked && worstHazard) {
    if (resolvedRealRoute && resolvedRealRoute.detourPath && resolvedRealRoute.detourPath.length > 0) {
      detourPath = resolvedRealRoute.detourPath;
    } else if (isDefaultCorridor && defaultDetour && defaultDetour.length > 0) {
      detourPath = defaultDetour;
    } else {
      // Fallback elevated detour
      const perpLat = -(destination.lng - origin.lng) * 0.35;
      const perpLng = (destination.lat - origin.lat) * 0.35;
      detourPath = [
        [origin.lat, origin.lng],
        [origin.lat + (destination.lat - origin.lat) * 0.3 + perpLat * 0.6, origin.lng + (destination.lng - origin.lng) * 0.3 + perpLng * 0.6],
        [origin.lat + (destination.lat - origin.lat) * 0.5 + perpLat, origin.lng + (destination.lng - origin.lng) * 0.5 + perpLng],
        [origin.lat + (destination.lat - origin.lat) * 0.7 + perpLat * 0.6, origin.lng + (destination.lng - origin.lng) * 0.7 + perpLng * 0.6],
        [destination.lat, destination.lng]
      ];
    }
  } else {
    detourPath = [...directPath];
  }

  const directDistanceKm = (resolvedRealRoute && resolvedRealRoute.distanceKm)
    ? resolvedRealRoute.distanceKm
    : Math.max(1.2, parseFloat(baseDistance.toFixed(1)));
  const directTimeMins = (resolvedRealRoute && resolvedRealRoute.durationMins)
    ? resolvedRealRoute.durationMins
    : Math.max(4, Math.round(directDistanceKm * 2.4));
  const detourDistanceKm = isBlocked ? parseFloat((directDistanceKm * 1.28).toFixed(1)) : directDistanceKm;
  const detourTimeMins = isBlocked ? directTimeMins + 4 : directTimeMins;

  const hazardName = worstHazard ? worstHazard.roadName : "No Water Hazard";
  const hazardDepth = worstHazard ? worstHazard.depthCm : 0;

  // Dynamic Audio Radar Alerts
  let speechHindi = "";
  let speechEnglish = "";

  if (isBlocked) {
    speechHindi = `सावधान! ${hazardName} पर ${hazardDepth} सेंटीमीटर पानी भरा है। बाइक के लिए तुरंत फ्लाइओवर वाला रास्ता लें।`;
    speechEnglish = `Caution! Severe waterlogging of ${hazardDepth} cm at ${hazardName}. Diverting via safe elevated bypass.`;
  } else if (hazardDepth > 0) {
    speechHindi = `मार्ग खुला है। ${hazardName} पर पानी ${hazardDepth} सेमी है। वाहन धीमी गति से निकालें।`;
    speechEnglish = `Route open. Minor waterlogging of ${hazardDepth} cm detected at ${hazardName}. Proceed with caution.`;
  } else {
    speechHindi = `मार्ग पूरी तरह सूखा और सुरक्षित है। कोई जलभराव नहीं है।`;
    speechEnglish = `Route is completely clear and dry. Safe journey.`;
  }

  return {
    origin,
    destination,
    hazardName,
    hazardDepth,
    directPath,
    detourPath,
    isDetourRequired: isBlocked,
    distanceKm: isBlocked ? detourDistanceKm : directDistanceKm,
    estTimeMins: isBlocked ? detourTimeMins : directTimeMins,
    avoidedDepth: isBlocked ? hazardDepth : 0,
    speechHindi,
    speechEnglish,
    advisoryText: isBlocked
      ? `Water at ${hazardName} is ${hazardDepth} cm deep (exceeds ${vehicle} safe limit of ${limit} cm). Diverting via elevated flyover bypass (+4 mins).`
      : hazardDepth > 0
      ? `Water at ${hazardName} is ${hazardDepth} cm deep. Passable for ${vehicle} within safe threshold.`
      : `Direct corridor clear of flood hazards. Normal dry transit.`
  };
}
